CREATE TABLE public.institution_area_reviews(institution_id uuid NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE,subject text NOT NULL,status text NOT NULL CHECK(status IN ('approved','rejected')),reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 5 AND 1000),reviewer_id uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(institution_id,subject));
GRANT SELECT ON public.institution_area_reviews TO authenticated; GRANT ALL ON public.institution_area_reviews TO service_role;
ALTER TABLE public.institution_area_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY area_review_read ON public.institution_area_reviews FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR coalesce(public.institution_role_of(institution_id)='direccion',false));
CREATE TABLE public.institution_area_review_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),institution_id uuid NOT NULL,subject text NOT NULL,actor_id uuid NOT NULL,before_value jsonb,after_value jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.institution_area_review_history TO authenticated; GRANT ALL ON public.institution_area_review_history TO service_role;
ALTER TABLE public.institution_area_review_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY area_history_read ON public.institution_area_review_history FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR coalesce(public.institution_role_of(institution_id)='direccion',false));
CREATE FUNCTION public.review_institution_area(_inst uuid,_subject text,_approved boolean,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE prior jsonb; nextrow jsonb; BEGIN
IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(),'admin') OR coalesce(public.institution_role_of(_inst)='direccion',false)) THEN RAISE EXCEPTION 'Sin permiso' USING ERRCODE='42501'; END IF;
IF _approved IS NULL OR _subject IS NULL OR length(btrim(_subject)) NOT BETWEEN 1 AND 150 OR _reason IS NULL OR length(btrim(_reason)) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'Decisión o motivo inválido'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.institution_publications WHERE institution_id=_inst AND subject=btrim(_subject) AND kind IN ('practica','simulacro')) THEN RAISE EXCEPTION 'Área no registrada'; END IF;
PERFORM 1 FROM public.institutions WHERE id=_inst FOR UPDATE;
SELECT to_jsonb(r) INTO prior FROM public.institution_area_reviews r WHERE institution_id=_inst AND subject=btrim(_subject);
INSERT INTO public.institution_area_reviews(institution_id,subject,status,reason,reviewer_id) VALUES(_inst,btrim(_subject),CASE WHEN _approved THEN 'approved' ELSE 'rejected' END,btrim(_reason),auth.uid()) ON CONFLICT(institution_id,subject) DO UPDATE SET status=excluded.status,reason=excluded.reason,reviewer_id=excluded.reviewer_id,updated_at=now() RETURNING to_jsonb(institution_area_reviews) INTO nextrow;
INSERT INTO public.institution_area_review_history(institution_id,subject,actor_id,before_value,after_value) VALUES(_inst,btrim(_subject),auth.uid(),prior,nextrow); END $$;
REVOKE ALL ON FUNCTION public.review_institution_area(uuid,text,boolean,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.review_institution_area(uuid,text,boolean,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.institution_topic_visible(_inst uuid,_subject text,_topic text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR coalesce(public.institution_role_of(_inst) IN ('direccion','subdireccion','docente','administrativo'),false) OR (EXISTS(SELECT 1 FROM public.institution_area_reviews r WHERE r.institution_id=_inst AND r.subject=_subject AND r.status='approved') AND EXISTS(SELECT 1 FROM public.student_institution_visibility v JOIN public.institution_members m ON m.institution_id=v.institution_id AND m.user_id=v.student_id AND m.member_role='estudiante' WHERE v.institution_id=_inst AND v.student_id=auth.uid() AND (_subject=ANY(v.areas) OR _topic=ANY(v.topics)))) $$;